// Per-panel car meshes (workstream R): the procedural low-poly mesh of a car
// (data/panels/meshes/<car>.json, generated by tools/assets) drawn as one Three.js mesh per part,
// every vertex skinned to its region's lattice nodes so dents show on every panel.
//
// Free panels (unlatched doors/hood/trunk, hanging bumpers/fenders) are rigid bodies in the sim:
// their lattice nodes are already rotated about the hinge. Plain displacement blending would
// smear a rotated door, so for those panels we fit the panel's rigid frame from three of its
// nodes (rest → current), take the dent in that frame and put the vertices back through it.
// Detached panels leave the car as visual debris (ballistic, bounce on the road; the physics
// debris body lives in Rapier and is not exposed to the browser yet).
//
// Coordinates: chassis space (+X right, +Y forward, +Z up), metres. The parent VehicleView root
// is already in that frame.
import * as THREE from "three";
import * as wasm from "../wasm/pkg/wp_wasm.js";
import { sim } from "../wasm/sim";

/** Floats per panel in wasm `panel_states()` (mirrors crates/wp_wasm PANEL_STRIDE). */
export const PANEL_STRIDE = 10;
/** Panel state codes (mirrors wp_damage::PanelState::code). */
export const PANEL_STATE = { attached: 0, unlatched: 1, hanging: 2, detached: 3 } as const;

/** One part of data/panels/meshes/<car>.json (tools/assets/src/mesh.rs `MeshPart`). */
export interface MeshPartJson {
  name: string;
  region: string | null;
  kind: "panel" | "glass" | "light" | "mirror" | "body" | "interior" | "tire" | "rim";
  material: "paint" | "glass" | "trim" | "headlight" | "taillight" | "rubber" | "metal" | "interior";
  wheel?: number | null;
  positions_mm: number[];
  uvs: number[];
  indices: number[];
  skin_nodes: number[];
  skin_weights: number[];
}

/** data/panels/meshes/<car>.json (`CarMesh`). */
export interface CarMeshJson {
  id: string;
  lattice_id: string;
  format: number;
  tri_count: number;
  parts: MeshPartJson[];
}

const meshCache = new Map<string, Promise<CarMeshJson | null>>();

/** Fetch (once per car) a car's panel mesh; null if the file is missing. */
export function loadCarMesh(carId: string): Promise<CarMeshJson | null> {
  let p = meshCache.get(carId);
  if (!p) {
    p = fetch(`data/panels/meshes/${carId}.json`)
      .then((r) => (r.ok ? (r.json() as Promise<CarMeshJson>) : null))
      .catch(() => null);
    meshCache.set(carId, p);
  }
  return p;
}

/** Panel states of an entity, PANEL_STRIDE floats per panel (empty if the build or scenario has none). */
export function panelStates(entity: number): Float32Array {
  const fn = (wasm as unknown as { panel_states?: (e: number) => Float32Array }).panel_states;
  if (typeof fn !== "function") return new Float32Array(0);
  try {
    return fn(entity);
  } catch {
    return new Float32Array(0);
  }
}

interface PartRT {
  def: MeshPartJson;
  mesh: THREE.Mesh;
  pos: Float32Array;
  rest: Float32Array;
  nodes: Uint16Array;
  weights: Float32Array;
  /** Index into `info.regions`, -1 for wheel parts. */
  region: number;
  hidden: boolean;
}

/** Rigid frame of a free panel: x' = R x + t. */
interface Frame {
  r: THREE.Matrix3;
  rt: THREE.Matrix3;
  t: THREE.Vector3;
}

interface Debris {
  obj: THREE.Group;
  vel: THREE.Vector3;
  spin: THREE.Vector3;
  age: number;
}

const bodies = new Map<number, PanelBody>();
const debris: Debris[] = [];
const MAX_DEBRIS = 48;
const DEBRIS_LIFE_S = 40;

/** Feed drained sim events (GlassShattered hides the glass part). Call once per frame. */
export function panelEvents(events: Record<string, Record<string, unknown>>[]): void {
  for (const e of events) {
    const g = e.GlassShattered;
    if (g) bodies.get(Number(g.vehicle))?.shatter(String(g.region));
  }
}

/** Advance visual debris (call once per frame with the frame dt). */
export function stepDebris(dt: number): void {
  for (let i = debris.length - 1; i >= 0; i--) {
    const d = debris[i];
    d.age += dt;
    d.vel.z -= 9.81 * dt;
    d.obj.position.addScaledVector(d.vel, dt);
    const e = new THREE.Euler(d.spin.x * dt, d.spin.y * dt, d.spin.z * dt);
    d.obj.quaternion.multiply(new THREE.Quaternion().setFromEuler(e));
    if (d.obj.position.z < 0.08) {
      d.obj.position.z = 0.08;
      if (d.vel.z < 0) d.vel.z = -0.25 * d.vel.z;
      d.vel.x *= 0.7;
      d.vel.y *= 0.7;
      d.spin.multiplyScalar(0.6);
    }
    if (d.age > DEBRIS_LIFE_S) {
      d.obj.removeFromParent();
      debris.splice(i, 1);
    }
  }
}

/** Remove all visual debris (scene reset). */
export function clearDebris(): void {
  for (const d of debris) d.obj.removeFromParent();
  debris.length = 0;
}

/** Number of visual debris pieces (tests / HUD). */
export function debrisCount(): number {
  return debris.length;
}

/** All per-panel meshes of one vehicle. Empty (ready = false) until the mesh file loads. */
export class PanelBody {
  readonly root = new THREE.Group();
  ready = false;
  /** Parts per wheel index, hub space (VehicleView parents them under its spinning wheel groups). */
  readonly wheelParts: THREE.Mesh[][] = [[], [], [], []];
  /** Latest panel states (PANEL_STRIDE floats per panel). */
  states: Float32Array = new Float32Array(0);
  private parts: PartRT[] = [];
  private readonly regions: string[];
  private restNodes: Float32Array = new Float32Array(0);
  /** Region index → three node ids spanning the panel (frame fit), for panel regions. */
  private readonly tri = new Map<number, [number, number, number]>();
  private readonly frames = new Map<number, Frame>();
  private readonly spawned = new Set<number>();
  private readonly mats: Record<MeshPartJson["material"], THREE.Material>;
  private onReady: (() => void) | null = null;

  constructor(
    readonly entity: number,
    readonly carId: string,
    paint: THREE.Color | number,
    headlight: THREE.Material,
    taillight: THREE.Material,
  ) {
    this.regions = sim.info(entity).regions;
    const std = (o: THREE.MeshStandardMaterialParameters) =>
      new THREE.MeshStandardMaterial({ flatShading: true, side: THREE.DoubleSide, ...o });
    this.mats = {
      paint: std({ color: paint, metalness: 0.25, roughness: 0.55 }),
      glass: std({ color: 0x8fb3c4, transparent: true, opacity: 0.38, metalness: 0.1, roughness: 0.1, depthWrite: false }),
      trim: std({ color: 0x1b1b1d, roughness: 0.9 }),
      headlight,
      taillight,
      rubber: std({ color: 0x141414, roughness: 0.95 }),
      metal: std({ color: 0x9da3a8, metalness: 0.7, roughness: 0.35 }),
      interior: std({ color: 0x2b2724, roughness: 1 }),
    };
    bodies.set(entity, this);
    // The car may be gone by the time its mesh arrives (a promoted traffic car demoted again
    // between two frames): then there is nothing to build; the view is disposed next frame.
    void loadCarMesh(carId).then((m) => {
      if (!m || bodies.get(entity) !== this) return;
      try {
        this.build(m);
      } catch {
        // wp_wasm: unknown entity — the sim already removed the vehicle.
      }
    });
  }

  /** Called once the mesh has loaded (immediately if it already has). */
  whenReady(fn: () => void): void {
    if (this.ready) fn();
    else this.onReady = fn;
  }

  /** Paint material (livery colour). */
  get paint(): THREE.MeshStandardMaterial {
    return this.mats.paint as THREE.MeshStandardMaterial;
  }

  private build(mesh: CarMeshJson): void {
    this.restNodes = sim.latticeRest(this.entity);
    const nodeRegions = sim.latticeRegions(this.entity);
    for (const def of mesh.parts) {
      const n = def.positions_mm.length / 3;
      const rest = new Float32Array(n * 3);
      for (let i = 0; i < n * 3; i++) rest[i] = def.positions_mm[i] * 1e-3;
      const geom = new THREE.BufferGeometry();
      const pos = rest.slice();
      geom.setAttribute("position", new THREE.BufferAttribute(pos, 3));
      const uv = new Float32Array(def.uvs.length);
      for (let i = 0; i < uv.length; i++) uv[i] = def.uvs[i] / 65535;
      geom.setAttribute("uv", new THREE.BufferAttribute(uv, 2));
      geom.setIndex(def.indices);
      const m = new THREE.Mesh(geom, this.mats[def.material]);
      m.name = def.name;
      m.frustumCulled = false;
      if (def.material === "glass") m.renderOrder = 1;
      const region = def.region ? this.regions.indexOf(def.region) : -1;
      if (def.wheel != null) {
        this.wheelParts[def.wheel].push(m);
        continue;
      }
      this.root.add(m);
      const w = new Float32Array(def.skin_weights.length);
      for (let i = 0; i < w.length; i++) w[i] = def.skin_weights[i] / 255;
      this.parts.push({ def, mesh: m, pos, rest, nodes: Uint16Array.from(def.skin_nodes), weights: w, region, hidden: false });
      if (region >= 0 && !this.tri.has(region)) this.tri.set(region, spanTriangle(this.restNodes, nodeRegions, region));
    }
    this.ready = true;
    this.update(this.restNodes, 0);
    this.onReady?.();
  }

  /** Hide a shattered glass region. */
  shatter(region: string): void {
    for (const p of this.parts) {
      if (p.def.region === region && p.def.kind === "glass") {
        p.hidden = true;
        p.mesh.visible = false;
      }
    }
  }

  /**
   * Re-skin every part from the current lattice nodes (chassis space, xyz per node) and the
   * panel states. `worldVel` (the car's world velocity, m/s) seeds detached-panel debris.
   */
  update(nodes: Float32Array, dt: number, worldVel?: THREE.Vector3): void {
    if (!this.ready) return;
    this.states = panelStates(this.entity);
    this.frames.clear();
    for (let k = 0; k + PANEL_STRIDE <= this.states.length; k += PANEL_STRIDE) {
      const region = this.states[k];
      const state = this.states[k + 1];
      if (state === PANEL_STATE.unlatched || state === PANEL_STATE.hanging) {
        const tri = this.tri.get(region);
        if (tri) this.frames.set(region, fitFrame(this.restNodes, nodes, tri));
      } else if (state === PANEL_STATE.detached && !this.spawned.has(region)) {
        this.spawned.add(region);
        if (dt > 0) this.spawnDebris(region, worldVel ?? new THREE.Vector3());
        else this.hideRegion(region);
      }
    }
    const rn = this.restNodes;
    const tmp = new THREE.Vector3();
    for (const p of this.parts) {
      if (p.hidden) continue;
      const f = p.region >= 0 ? this.frames.get(p.region) : undefined;
      const { rest, pos, nodes: ids, weights } = p;
      const nv = rest.length / 3;
      for (let v = 0; v < nv; v++) {
        let dx = 0;
        let dy = 0;
        let dz = 0;
        for (let k = 0; k < 4; k++) {
          const w = weights[v * 4 + k];
          if (w === 0) continue;
          const i = ids[v * 4 + k] * 3;
          if (f) {
            // Node in the panel's own frame, minus its rest position = dent.
            tmp.set(nodes[i] - f.t.x, nodes[i + 1] - f.t.y, nodes[i + 2] - f.t.z).applyMatrix3(f.rt);
            dx += w * (tmp.x - rn[i]);
            dy += w * (tmp.y - rn[i + 1]);
            dz += w * (tmp.z - rn[i + 2]);
          } else {
            dx += w * (nodes[i] - rn[i]);
            dy += w * (nodes[i + 1] - rn[i + 1]);
            dz += w * (nodes[i + 2] - rn[i + 2]);
          }
        }
        if (f) {
          tmp.set(rest[v * 3] + dx, rest[v * 3 + 1] + dy, rest[v * 3 + 2] + dz).applyMatrix3(f.r).add(f.t);
          pos[v * 3] = tmp.x;
          pos[v * 3 + 1] = tmp.y;
          pos[v * 3 + 2] = tmp.z;
        } else {
          pos[v * 3] = rest[v * 3] + dx;
          pos[v * 3 + 1] = rest[v * 3 + 1] + dy;
          pos[v * 3 + 2] = rest[v * 3 + 2] + dz;
        }
      }
      (p.mesh.geometry.getAttribute("position") as THREE.BufferAttribute).needsUpdate = true;
    }
  }

  private hideRegion(region: number): void {
    for (const p of this.parts) {
      if (p.region === region) {
        p.hidden = true;
        p.mesh.visible = false;
      }
    }
  }

  /** Move a detached region's parts out of the car into world-space debris. */
  private spawnDebris(region: number, worldVel: THREE.Vector3): void {
    const parent = this.root.parent?.parent; // VehicleView.root → world group
    const car = this.root.parent;
    if (!parent || !car) return this.hideRegion(region);
    const group = new THREE.Group();
    group.position.copy(car.position);
    group.quaternion.copy(car.quaternion);
    const centroid = new THREE.Vector3();
    let count = 0;
    for (const p of this.parts) {
      if (p.region !== region || p.hidden) continue;
      const geom = new THREE.BufferGeometry();
      geom.setAttribute("position", new THREE.BufferAttribute(p.pos.slice(), 3));
      geom.setIndex(p.def.indices);
      const m = new THREE.Mesh(geom, p.mesh.material);
      m.frustumCulled = false;
      group.add(m);
      for (let i = 0; i < p.pos.length; i += 3) {
        centroid.x += p.pos[i];
        centroid.y += p.pos[i + 1];
        centroid.z += p.pos[i + 2];
        count++;
      }
      p.hidden = true;
      p.mesh.visible = false;
    }
    if (count === 0) return;
    centroid.multiplyScalar(1 / count);
    // Pivot the debris about its own centre so it tumbles believably.
    for (const c of group.children) c.position.sub(centroid);
    group.position.add(centroid.clone().applyQuaternion(car.quaternion));
    parent.add(group);
    // Thrown outward from the car's centre, a little up; spin from the region index (deterministic).
    const out = new THREE.Vector3(centroid.x, centroid.y, 0).normalize().applyQuaternion(car.quaternion);
    const vel = worldVel.clone().addScaledVector(out, 1.5);
    vel.z += 1.2;
    const s = (region % 5) - 2;
    debris.push({ obj: group, vel, spin: new THREE.Vector3(1.5 + s * 0.4, -1.0 + s * 0.3, 0.8 - s * 0.2), age: 0 });
    while (debris.length > MAX_DEBRIS) debris.shift()?.obj.removeFromParent();
  }

  dispose(): void {
    bodies.delete(this.entity);
    this.root.removeFromParent();
  }
}

/** Three nodes of `region` spanning the largest triangle (rest pose). */
function spanTriangle(rest: Float32Array, regions: Uint8Array, region: number): [number, number, number] {
  const ids: number[] = [];
  for (let i = 0; i < regions.length; i++) if (regions[i] === region) ids.push(i);
  let best: [number, number, number] = [ids[0] ?? 0, ids[1] ?? 0, ids[2] ?? 0];
  let area = -1;
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const c = new THREE.Vector3();
  for (let i = 0; i < ids.length; i++)
    for (let j = i + 1; j < ids.length; j++)
      for (let k = j + 1; k < ids.length; k++) {
        a.fromArray(rest, ids[i] * 3);
        b.fromArray(rest, ids[j] * 3).sub(a);
        c.fromArray(rest, ids[k] * 3).sub(a);
        const ar = b.cross(c).lengthSq();
        if (ar > area) {
          area = ar;
          best = [ids[i], ids[j], ids[k]];
        }
      }
  return best;
}

/** Orthonormal frame of a node triangle as columns. */
function triFrame(p: Float32Array, [i, j, k]: [number, number, number]): { m: THREE.Matrix3; o: THREE.Vector3 } {
  const o = new THREE.Vector3().fromArray(p, i * 3);
  const e1 = new THREE.Vector3().fromArray(p, j * 3).sub(o).normalize();
  const c = new THREE.Vector3().fromArray(p, k * 3).sub(o);
  const e3 = new THREE.Vector3().crossVectors(e1, c).normalize();
  const e2 = new THREE.Vector3().crossVectors(e3, e1);
  const m = new THREE.Matrix3().set(e1.x, e2.x, e3.x, e1.y, e2.y, e3.y, e1.z, e2.z, e3.z);
  return { m, o };
}

/** Rigid transform taking the triangle's rest frame to its current frame. */
function fitFrame(rest: Float32Array, cur: Float32Array, tri: [number, number, number]): Frame {
  const a = triFrame(rest, tri);
  const b = triFrame(cur, tri);
  const r = b.m.clone().multiply(a.m.clone().transpose());
  const t = b.o.clone().sub(a.o.clone().applyMatrix3(r));
  return { r, rt: r.clone().transpose(), t };
}
